  "Stage value": ["Значение этапа", "Этап кыйммәте"],
  "Ordered stages": ["Упорядоченные этапы", "Тәртипләнгән этаплар"],
  "Funnel population": ["Совокупность воронки", "Бүрәнкә җыелмасы"],
